<?php
namespace App\Services;use App\Models\{GeneratedReport,Employee,AttendanceRecord,AdvancePayment,ExtraDuty,Payslip};use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;use Barryvdh\DomPDF\Facade\Pdf;use ZipArchive;
class ReportGenerationService{public function generate(string $type,string $file,array $filters,?int $uid=null):GeneratedReport{@mkdir(storage_path('app/reports'),0777,true);$base=$type.'_'.date('Ymd_His');$ext=$file==='excel'?'xlsx':($file==='zip'?'zip':'pdf');$rel='reports/'.$base.'.'.$ext;$abs=storage_path('app/'.$rel);if($file==='zip')$this->zip($abs,$filters);else{[$h,$rows]=$this->data($type,$filters);if($file==='excel')$this->xlsx($h,$rows,$abs);else Pdf::loadView('reports.table',['title'=>$type,'headers'=>$h,'rows'=>$rows])->save($abs);}return GeneratedReport::create(['report_type'=>$type,'report_name'=>ucwords(str_replace('_',' ',$type)),'project_id'=>$filters['project_id']??null,'employee_id'=>$filters['employee_id']??null,'month'=>$filters['month']??null,'year'=>$filters['year']??null,'filters'=>$filters,'file_type'=>$file,'file_path'=>$rel,'generated_by'=>$uid,'generated_at'=>now(),'status'=>'completed']);}public function generateAll($filters,$uid=null){return $this->generate('all_reports','zip',$filters,$uid);}function data($t,$f){$m=$f['month']??null;$y=$f['year']??null;$pid=$f['project_id']??null;if(str_contains($t,'attendance')||$t==='absent'){$q=AttendanceRecord::with('employee','project')->when($pid,fn($x)=>$x->where('project_id',$pid))->when($m,fn($x)=>$x->where('month',$m))->when($y,fn($x)=>$x->where('year',$y));if($t==='absent')$q->where('status','absent');$rows=$q->limit(5000)->get()->map(fn($r)=>['Date'=>$r->attendance_date?->format('Y-m-d'),'Employee'=>$r->employee?->name,'Project'=>$r->project?->name,'Status'=>$r->status,'Hours'=>$r->hours])->all();return [['Date','Employee','Project','Status','Hours'],$rows];}if(str_contains($t,'advance')){$rows=AdvancePayment::with('employee','project')->get()->map(fn($r)=>['Date'=>$r->payment_date?->format('Y-m-d'),'Employee'=>$r->employee?->name,'Project'=>$r->project?->name,'Amount'=>$r->amount])->all();return [['Date','Employee','Project','Amount'],$rows];}if(str_contains($t,'extra')||str_contains($t,'friday')){$rows=ExtraDuty::with('employee','project')->get()->map(fn($r)=>['Date'=>$r->duty_date?->format('Y-m-d'),'Employee'=>$r->employee?->name,'Type'=>$r->day_type,'Hours'=>$r->hours_worked,'Amount'=>$r->amount,'Status'=>$r->approval_status])->all();return [['Date','Employee','Type','Hours','Amount','Status'],$rows];}if(str_contains($t,'pay')||str_contains($t,'salary')){$rows=Payslip::with('employee','project')->get()->map(fn($r)=>['Employee'=>$r->employee?->name,'Gross'=>$r->gross_salary,'Advance'=>$r->advance_deduction,'Net'=>$r->net_salary,'Status'=>$r->status])->all();return [['Employee','Gross','Advance','Net','Status'],$rows];}$rows=Employee::with('designation','company','currentProject')->get()->map(fn($e)=>['Code'=>$e->employee_code,'Name'=>$e->name,'Iqama'=>$e->iqama_no,'Designation'=>$e->designation?->name,'Company'=>$e->company?->name,'Project'=>$e->currentProject?->name,'Status'=>$e->status])->all();return [['Code','Name','Iqama','Designation','Company','Project','Status'],$rows];}function xlsx($h,$rows,$path){$s=new Spreadsheet;$sh=$s->getActiveSheet();foreach($h as $i=>$v)$sh->setCellValueByColumnAndRow($i+1,1,$v);$r=2;foreach($rows as $row){foreach(array_values($row) as $i=>$v)$sh->setCellValueByColumnAndRow($i+1,$r,$v);$r++;}(new Xlsx($s))->save($path);}function zip($path,$filters){$z=new ZipArchive;$z->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE);foreach(['employee_list','monthly_attendance','absent','advance_payments','extra_duties','payslips'] as $t){[$h,$r]=$this->data($t,$filters);$tmp=storage_path('app/reports/'.$t.'.xlsx');$this->xlsx($h,$r,$tmp);$z->addFile($tmp,basename($tmp));}$z->close();}}
